package com.git.aidocument;
import android.app.*; import android.widget.Toast; import android.os.*; import android.content.*; import android.net.Uri; import android.webkit.*; import java.io.*; import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity {
 WebView web; String currentName="Ghi-chu.txt", pending=""; static final int OPEN=100,SAVE=101;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xfff7faff);getWindow().setNavigationBarColor(0xffffffff);getWindow().getDecorView().setSystemUiVisibility(android.view.View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|android.view.View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);web=new WebView(this);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.addJavascriptInterface(new Bridge(),"Android");web.loadUrl("file:///android_asset/index.html");}
 class Bridge {
 @JavascriptInterface public void open(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,OPEN);});}
 @JavascriptInterface public void save(String value){runOnUiThread(()->{pending=value;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/plain");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,currentName.endsWith(".txt")?currentName:"GIT-Note.txt");startActivityForResult(i,SAVE);});}
 @JavascriptInterface public void share(String value){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,value);startActivity(Intent.createChooser(i,"Chia sẻ nội dung"));});}
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;Uri uri=data.getData();if(uri==null)return;try{if(request==SAVE){try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(pending.getBytes(StandardCharsets.UTF_8));}toast("Đã lưu tài liệu");}else{String name="Tài liệu";try(android.database.Cursor c=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}currentName=name;if(name.toLowerCase().endsWith(".txt")||name.toLowerCase().endsWith(".md")){ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(uri)){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>2000000)break;out.write(buffer,0,n);}}web.evaluateJavascript("loadDocument("+org.json.JSONObject.quote(name)+","+org.json.JSONObject.quote(out.toString("UTF-8"))+")",null);}else{Intent view=new Intent(Intent.ACTION_VIEW);view.setDataAndType(uri,getContentResolver().getType(uri));view.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(view);}catch(Exception e){toast("Cần cài ứng dụng đọc Word, Excel hoặc PDF");}}}}catch(Exception e){toast("Không thể xử lý tệp");}}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 @Override public void onBackPressed(){web.evaluateJavascript("goHome()",null);}
}